form.script:
document.addEventListener('DOMContentLoaded', function() {
    const typeFilter = document.getElementById('vehicle_type_filter');
    const vehicleSelect = document.getElementById('vehicle_id');
    const galleryContainer = document.getElementById('vehicle_gallery_container');
    const galleryItems = document.querySelectorAll('.vehicle-gallery-item');
    const allOptions = Array.from(vehicleSelect.options).slice(1);

    typeFilter.addEventListener('change', function() {
        const selectedType = this.value;

        // 1. Update Dropdown
        vehicleSelect.innerHTML = '-- กรุณาเลือกรถ --';
        if (!selectedType) {
            vehicleSelect.disabled = true;
            galleryContainer.classList.add('d-none');
            return;
        }

        let found = false;
        allOptions.forEach(opt => {
            if (opt.getAttribute('data-type') === selectedType) {
                vehicleSelect.appendChild(opt);
                found = true;
            }
        });
        vehicleSelect.disabled = !found;

        // 2. Update Gallery
        galleryContainer.classList.remove('d-none');
        galleryItems.forEach(item => {
            item.style.display = (item.getAttribute('data-type') === selectedType) ? 'block' : 'none';
        });
    });
});

div.script:
(function() {
    function pad(n) { return n.toString().padStart(2, '0'); }
    function formatDisplay(d) {
        return d.getDate() + '/' + pad(d.getMonth()+1) + '/' + d.getFullYear() +
               ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }
    function formatInput(d) {
        return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) +
               'T' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }

    var now = new Date();

    // set hidden field
    var ds = document.getElementById('date_start');
    if (ds) ds.value = formatInput(now);

    // set display label
    var disp_s = document.getElementById('display_start');
    if (disp_s) disp_s.textContent = formatDisplay(now);
})();

document.addEventListener('DOMContentLoaded', function() {
    const editBtns = document.querySelectorAll('.edit-vehicle-btn');
    const editModalFieldId = document.getElementById('edit_vehicle_id');
    const editModalFieldPlate = document.getElementById('edit_license_plate');
    const editModalFieldModel = document.getElementById('edit_model_name');

    editBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            if (editModalFieldId) editModalFieldId.value = this.dataset.id;
            if (editModalFieldPlate) editModalFieldPlate.value = this.dataset.license_plate;
            if (editModalFieldModel) editModalFieldModel.value = this.dataset.model_name;
        });
    });

    // Transfer Modal Data Filling
    const transferBtns = document.querySelectorAll('.transfer-vehicle-btn');
    const transModalId = document.getElementById('transfer_vehicle_id');
    const transModalName = document.getElementById('transfer_vehicle_name');
    const transModalFrom = document.getElementById('transfer_from_factory');

    transferBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            if (transModalId) transModalId.value = this.dataset.id;
            if (transModalName) transModalName.textContent = this.dataset.name;
            if (transModalFrom) transModalFrom.textContent = this.dataset.factory;
        });
    });
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
    const typeFilter = document.getElementById('repair_type_filter');
    const vehicleSelect = document.getElementById('repair_vehicle_id');

    if (typeFilter && vehicleSelect) {
        const allOptions = Array.from(vehicleSelect.options).slice(1);
        typeFilter.addEventListener('change', function() {
            const selectedType = this.value;
            vehicleSelect.innerHTML = '-- เลือกคัน --';

            if (!selectedType) {
                vehicleSelect.disabled = true;
                return;
            }

            let count = 0;
            allOptions.forEach(opt => {
                if (opt.getAttribute('data-type') === selectedType) {
                    vehicleSelect.appendChild(opt.cloneNode(true));
                    count++;
                }
            });
            vehicleSelect.disabled = count === 0;
        });
    }

    // Handle Finish Repair Modal Data Filling
    const finishRepairModal = document.getElementById('finishRepairModal');
    if (finishRepairModal) {
        finishRepairModal.addEventListener('show.bs.modal', function (event) {
            // Button that triggered the modal
            const button = event.relatedTarget;
            // Extract info from data-bs-* attributes
            const repairId = button.getAttribute('data-id');
            const vehicleName = button.getAttribute('data-name');

            // Update the modal's content
            const modalIdInput = finishRepairModal.querySelector('#modal_repair_id');
            const modalVehicleName = finishRepairModal.querySelector('#modal_vehicle_name');

            if (modalIdInput) modalIdInput.value = repairId;
            if (modalVehicleName) modalVehicleName.textContent = vehicleName;
        });
    }
});

template.script:
document.addEventListener('DOMContentLoaded', function() {
    const modalTypeFilter = document.getElementById('modal_vehicle_type');
    const modalVehicleSelect = document.getElementById('modal_vehicle_id');

    if (modalTypeFilter && modalVehicleSelect) {
        const modalOpts = Array.from(modalVehicleSelect.options).slice(1);
        modalTypeFilter.addEventListener('change', function() {
            const sel = this.value;
            modalVehicleSelect.innerHTML = '-- เลือกรถ --';
            if (!sel) { modalVehicleSelect.disabled = true; return; }
            let count = 0;
            modalOpts.forEach(o => {
                if (o.getAttribute('data-type') === sel) {
                    modalVehicleSelect.appendChild(o.cloneNode(true));
                    count++;
                }
            });
            modalVehicleSelect.disabled = count === 0;
        });
    }
});

xpath.script:
function googleTranslateElementInit() {
    new google.translate.TranslateElement({
        pageLanguage: 'th',
        includedLanguages: 'th,en,my',
        autoDisplay: false
    }, 'google_translate_element');
}

// สคริปต์สั่งแปลอัตโนมัติเมื่อเปลี่ยนภาษา Odoo
(function() {
    var checkGoogleTranslate = setInterval(function() {
        var combo = document.querySelector('.goog-te-combo');
        if (combo) {
            clearInterval(checkGoogleTranslate);
            var currentLang = document.documentElement.lang.split('-')[0]; // 'th' or 'en' or 'my'

            // ถ้าไม่ใช่ภาษาไทย ให้สั่ง Google Translate ทำงาน
            if (currentLang && currentLang !== 'th') {
                combo.value = currentLang;
                combo.dispatchEvent(new Event('change'));
            }
        }
    }, 500);

    // ลบแถบ Google Top Bar ที่อาจจะโผล่มาทับหน้าเว็บ
    var style = document.createElement('style');
    style.innerHTML = 'body { top: 0 !important; } .goog-te-banner-frame { display: none !important; } .goog-te-balloon-frame { display: none !important; } .goog-tooltip { display: none !important; } .goog-tooltip:hover { display: none !important; } .preview-cm { display: none !important; }';
    document.head.appendChild(style);
})();

div.script:
(function() {
    try {
        const jsonData = document.getElementById('lot_details_json_data').textContent;
        window.LOT_DETAILS = JSON.parse(jsonData || '{}');
    } catch (e) {
        console.error('Error parsing LOT_DETAILS:', e);
        window.LOT_DETAILS = {};
    }
})();

                                document.addEventListener('DOMContentLoaded', function() {
                                    const partSelect = document.getElementById('issue_part_select');
                                    const qtyInput = document.getElementById('issue_qty');
                                    const warning = document.getElementById('qty_warning');
                                    const submitBtn = document.getElementById('issue_submit_btn');

                                    const lotSelect = document.getElementById('issue_lot_select');
                                    const unitPriceInput = document.getElementById('issue_unit_price');
                                    // lotDataItems removed

                                    function checkStock() {
                                        const selected = partSelect.options[partSelect.selectedIndex];
                                        if (selected && selected.value) {
                                            const stock = parseFloat(selected.getAttribute('data-qty') || 0);
                                            const qty = parseFloat(qtyInput.value || 0);
                                            if (qty > stock) {
                                                warning.classList.remove('d-none');
                                                submitBtn.disabled = true;
                                            } else {
                                                warning.classList.add('d-none');
                                                submitBtn.disabled = false;
                                            }

                                            // กรองล็อต
                                            updateLots(selected.value);
                                        } else {
                                            if (lotSelect) {
                                                lotSelect.innerHTML = '-- เลือกล็อต --';
                                                lotSelect.disabled = true;
                                            }
                                        }
                                    }

                                    function updateLots(partId) {
                                        if (!lotSelect) return;
                                        lotSelect.innerHTML = '-- เลือกล็อต --';
                                        let found = false;
                                        const lotData = (window.LOT_DETAILS || {})[partId] || {};

                                        Object.keys(lotData).forEach(lotName => {
                                            const info = lotData[lotName];
                                            if (info.qty > 0) {
                                                const opt = document.createElement('option');
                                                opt.value = lotName;
                                                opt.textContent = `${lotName} (คงเหลือ: ${info.qty.toLocaleString()})`;
                                                opt.dataset.price = info.price;
                                                lotSelect.appendChild(opt);
                                                found = true;
                                            }
                                        });
                                        lotSelect.disabled = !found;
                                        if (!found) lotSelect.innerHTML = '-- ไม่มีข้อมูลล็อต --';
                                    }

                                    if (lotSelect) {
                                        lotSelect.addEventListener('change', function() {
                                            const opt = this.options[this.selectedIndex];
                                            if (opt && opt.dataset.price) {
                                                unitPriceInput.value = opt.dataset.price;
                                            } else {
                                                unitPriceInput.value = '';
                                            }
                                        });
                                    }

                                    if (partSelect) partSelect.addEventListener('change', checkStock);
                                    if (qtyInput) qtyInput.addEventListener('input', checkStock);

                                    // เพิ่มระบบกรองรถในหน้าเบิกอะไหล่
                                    const issueTypeFilter = document.getElementById('issue_vehicle_type');
                                    const issueVehicleSelect = document.getElementById('issue_vehicle_id');

                                    if (issueTypeFilter && issueVehicleSelect) {
                                        const allIssueOptions = Array.from(issueVehicleSelect.options).slice(1);
                                        issueTypeFilter.addEventListener('change', function() {
                                            const selectedType = this.value;
                                            issueVehicleSelect.innerHTML = '-- ไม่ระบุ / ของส่วนกลาง --';

                                            allIssueOptions.forEach(opt => {
                                                if (!selectedType || opt.getAttribute('data-type') === selectedType) {
                                                    issueVehicleSelect.appendChild(opt.cloneNode(true));
                                                }
                                            });
                                        });
                                    }
                                    // ระบบ Modal แสดงรายละเอียดแยกตามล็อต (อ่านจาก JSON window.LOT_DETAILS)
                                    const sparePartRows = document.querySelectorAll('.spare-part-row');
                                    const modalLotBody = document.getElementById('modal_lot_body');
                                    const modalPartName = document.getElementById('modal_part_name');
                                    const modalTotalVal = document.getElementById('modal_total_val');
                                    const detailModal = document.getElementById('partLotDetailModal');

                                    // เก็บ row ที่คลิกล่าสุดเพื่อส่งให้ show.bs.modal
                                    let lastClickedRow = null;

                                    function populateModal(row) {
                                        if (!row) return;
                                        const partId = String(row.getAttribute('data-id') || '').trim();
                                        if (!partId) return;

                                        // ดึงชื่ออะไหล่จากหลายแหล่ง
                                        let partName = (row.getAttribute('data-name') || '').trim();
                                        if (!partName || partName === '---') {
                                            const nameEl = row.querySelector('.fw-semibold');
                                            if (nameEl) {
                                                partName = nameEl.textContent.trim();
                                            } else {
                                                const secondCell = row.cells ? row.cells[1] : null;
                                                partName = secondCell ? secondCell.textContent.trim() : 'ไม่พบชื่ออะไหล่';
                                            }
                                        }

                                        modalPartName.textContent = partName || '---';
                                        modalLotBody.innerHTML = '';
                                        let grandTotal = 0;
                                        let foundCount = 0;

                                        const allLotDetails = window.LOT_DETAILS || {};
                                        const lotData = allLotDetails[partId] || {};

                                        Object.keys(lotData).forEach(function(lotName) {
                                            const info = lotData[lotName];
                                            const qty = parseFloat(info.qty || 0);
                                            const price = parseFloat(info.price || 0);
                                            const total = qty * price;
                                            grandTotal += total;
                                            foundCount++;

                                            const tr = document.createElement('tr');
                                            const qtyBadge = qty > 0 ? 'bg-success' : 'bg-secondary';
                                            tr.innerHTML =
                                                '' + lotName + '' +
                                                '' + qty.toLocaleString() + '' +
                                                '฿ ' + price.toLocaleString(undefined,{minimumFractionDigits:2}) + '' +
                                                '฿ ' + total.toLocaleString(undefined,{minimumFractionDigits:2}) + '';
                                            modalLotBody.appendChild(tr);
                                        });

                                        modalTotalVal.textContent = '฿ ' + grandTotal.toLocaleString(undefined,{minimumFractionDigits:2});
                                        if (foundCount === 0) {
                                            modalLotBody.innerHTML = '
ยังไม่มีข้อมูลล็อตสำหรับอะไหล่ชิ้นนี้';
                                        }
                                    }

                                    // เก็บ row ที่คลิกล่าสุดไว้ใน lastClickedRow
                                    sparePartRows.forEach(function(row) {
                                        row.addEventListener('click', function() {
                                            lastClickedRow = this;
                                        });
                                    });

                                    // ใช้ show.bs.modal เป็น primary handler
                                    if (detailModal) {
                                        detailModal.addEventListener('show.bs.modal', function (event) {
                                            const triggerEl = event.relatedTarget || lastClickedRow;
                                            if (triggerEl) {
                                                populateModal(triggerEl);
                                            }
                                            lastClickedRow = null;
                                        });
                                    }
                                    // ระบบ Modal แก้ไขข้อมูลอะไหล่
                                    const editButtons = document.querySelectorAll('.edit-part-btn');
                                    const editModalEl = document.getElementById('editPartModal');
                                    const editModal = editModalEl ? new bootstrap.Modal(editModalEl) : null;

                                    editButtons.forEach(btn => {
                                        btn.addEventListener('click', function(e) {
                                            e.stopPropagation();
                                            if (editModal) {
                                                document.getElementById('edit_part_id').value = this.dataset.id;
                                                document.getElementById('edit_part_name').value = this.dataset.name;
                                                document.getElementById('edit_part_code').value = this.dataset.code || '';
                                                document.getElementById('edit_part_uom').value = this.dataset.uom || 'ชิ้น';
                                                document.getElementById('edit_part_min_qty').value = this.dataset.min_qty || '1.0';
                                                document.getElementById('edit_part_description').value = this.dataset.description || '';
                                                editModal.show();
                                            }
                                        });
                                    });
                                    });

document.addEventListener('DOMContentLoaded', function() {
    const histTypeFilter = document.getElementById('hist_vehicle_type');
    const histVehicleSelect = document.getElementById('hist_vehicle_id');

    if (histTypeFilter && histVehicleSelect) {
        const allHistOptions = Array.from(histVehicleSelect.options).slice(1);
        histTypeFilter.addEventListener('change', function() {
            const selectedType = this.value;
            histVehicleSelect.innerHTML = '-- ทั้งหมด --';

            allHistOptions.forEach(opt => {
                if (selectedType === 'all' || opt.getAttribute('data-type') === selectedType) {
                    histVehicleSelect.appendChild(opt.cloneNode(true));
                }
            });
        });
    }
});
